def test_point_all_null_opacity_column_falls_back_to_default():
    """All-null opacity column must fall back to batch-level default, not crash."""
    df = pl.DataFrame(
        {
            "x": [1.0, 2.0, 3.0],
            "y": [10.0, 20.0, 30.0],
            "op": [None, None, None],
        },
        schema={"x": pl.Float64, "y": pl.Float64, "op": pl.Float64},
    )
    chart = fr.Chart(df).mark_point().encode(x="x", y="y", opacity="op")
    svg = chart.show_svg()
    assert "NaN" not in svg
    assert svg.count("<circle") >= 3


