# ---------------------------------------------------------------------------
# SVG attribute emission contracts for per-instance styles
# ---------------------------------------------------------------------------


def test_fill_opacity_attr_only_when_less_than_one():
    """fill-opacity attribute should only be emitted when value < 1.0."""
    df = pl.DataFrame(
        {
            "x": [1.0, 2.0],
            "y": [10.0, 20.0],
            "fo": [1.0, 0.5],
        }
    )
    chart = fr.Chart(df).mark_point().encode(x="x", y="y", fill_opacity="fo")
    svg = chart.show_svg()
    # At least one element should have fill-opacity (the 0.5 one)
    assert "fill-opacity" in svg
    # Count: not all circles should have fill-opacity (only the < 1.0 one)
    fill_op_count = svg.count("fill-opacity")
    assert fill_op_count >= 1


def test_stroke_opacity_attr_only_when_less_than_one():
    """stroke-opacity attribute should only be emitted when value < 1.0."""
    df = pl.DataFrame(
        {
            "x": [1.0, 2.0],
            "y": [10.0, 20.0],
            "so": [1.0, 0.3],
        }
    )
    chart = fr.Chart(df).mark_point().encode(x="x", y="y", stroke_opacity="so")
    svg = chart.show_svg()
    # The 0.3 row should produce a stroke-opacity attribute
    assert "stroke-opacity" in svg


def test_angle_transform_emitted_for_nonzero_angle():
    """Non-zero angle encoding should produce a rotate transform in SVG."""
    df = pl.DataFrame(
        {
            "x": [1.0, 2.0, 3.0],
            "y": [10.0, 20.0, 30.0],
            "ang": [0.0, 45.0, 90.0],
        }
    )
    chart = fr.Chart(df).mark_point().encode(x="x", y="y", angle="ang")
    svg = chart.show_svg()
    # At least one element should have a rotate transform (45 or 90 degree rows)
    assert "rotate(" in svg


